-- Vietnam 2025 Administrative Reform - Single Import Script
-- 34 Provinces + Sample Communes

TRUNCATE administrative_units CASCADE;


-- Insert sample communes
WITH p AS (SELECT id, code FROM administrative_units WHERE code = '01')
SELECT 'Ba Đình', '00101', 'COMMUNE', id, ST_GeomFromText('POLYGON((105.82 21.03, 105.84 21.03, 105.84 21.05, 105.82 21.05, 105.82 21.03))', 4326), ST_GeomFromText('POINT(105.83 21.04)', 4326), 12.04, 247100, 20523, 'Đồng bằng sông Hồng' FROM p
UNION ALL
SELECT 'Hoàn Kiếm', '00102', 'COMMUNE', id, ST_GeomFromText('POLYGON((105.84 21.02, 105.88 21.02, 105.88 21.04, 105.84 21.04, 105.84 21.02))', 4326), ST_GeomFromText('POINT(105.86 21.03)', 4326), 9.22, 180200, 19545, 'Đồng bằng sông Hồng' FROM p;

WITH p AS (SELECT id, code FROM administrative_units WHERE code = '79')
SELECT 'Tân Bình', '07901', 'COMMUNE', id, ST_GeomFromText('POLYGON((106.62 10.78, 106.68 10.78, 106.68 10.84, 106.62 10.84, 106.62 10.78))', 4326), ST_GeomFromText('POINT(106.65 10.81)', 4326), 8.15, 445000, 54596, 'Đông Nam Bộ' FROM p
UNION ALL
SELECT 'Thủ Đức', '07902', 'COMMUNE', id, ST_GeomFromText('POLYGON((106.72 10.82, 106.80 10.82, 106.80 10.88, 106.72 10.88, 106.72 10.82))', 4326), ST_GeomFromText('POINT(106.76 10.85)', 4326), 48.11, 580000, 12056, 'Đông Nam Bộ' FROM p;

SELECT level, COUNT(*) as count FROM administrative_units GROUP BY level ORDER BY level;
